SELECT O978241.NOCONTACONTABIL, O996998.COCONTACONTABIL, O996998.COGESTAO, ( DECODE(SUBSTR(O996998.COCONTACONTABIL,1,1),1,O996998.VADEBITO-O996998.VACREDITO,3,O996998.VADEBITO-O996998.VACREDITO,5,O996998.VADEBITO-O996998.VACREDITO,8,O996998.VADEBITO-O996998.VACREDITO,O996998.VACREDITO-O996998.VADEBITO) ), O996998.COUG
FROM MIL2026.VCONTACONTABIL O978241, MIL2026.SALDOCONTABIL O996998
WHERE ( ( O978241.COCONTACONTABIL = O996998.COCONTACONTABIL ) ) AND ( O996998.INMES <= 6 ) AND ( O996998.COCONTACONTABIL IN (521920500,821191201) )
;
